"""Release gate for genai_assistant_service (generated by A2C v1.6 from a2c_sdlc.evaluation; _run_case
completed by hand).

E2A's ProjectReleaseGate runs the generic stages (secret scan, tests, strict conformance, compile) and
the domain ones on the evaluation sets: each case is run against the stand-ins of the four systems
(standins/landscape.py) and scored by E2A's scorers on its `expect` (e2a.evals: trajectory, refusal,
contains / forbidden, no_pii). The scored output is the assistant's whole answer as JSON (status,
answer, citations, proposal, receipt, degraded, gaps).

A case's input: query, and optionally tenant, user, role; "decide" {"approved", "by", "role"} decides
the approval the request created; "faults" {path prefix: status | "timeout"} and "model": "down"
inject failures. On the "simulated" profile the simulated model answers (services/simulated.py); on
gemini_api the bound model does, with the same checks.

    python -m genai_assistant_service.release.gate [--skip-tests] [--report release-gate-report.json]
"""
import json
import sys

from e2a.release import ProjectReleaseGate, run_release_gate

from genai_assistant_service.services.assistant import AssistantService, Forbidden, NotFound
from genai_assistant_service.standins.landscape import Landscape
from genai_assistant_service.tools.catalog import tools


class _Down:
    async def process_inference(self, *args, **kwargs):
        return {"status": "FAILED", "error": "429 RESOURCE_EXHAUSTED", "error_type": "QuotaExceeded"}


class ReleaseGate(ProjectReleaseGate):
    evaluation_set = "evals/golden.json"
    redteam_set = "evals/redteam.json"

    def _run_case(self, case):
        """Run the assistant on case["input"] against fresh stand-ins; return the final state, with the
        assistant's answer as state["response"] (what the scorers read)."""
        spec = dict(case.get("input") or {})
        landscape = Landscape()
        landscape.faults.update(spec.get("faults") or {})
        assistant = AssistantService(tools=tools(transports=landscape.transports()),
                                     llm=_Down() if spec.get("model") == "down" else None)
        tenant, user = spec.get("tenant", "acme"), spec.get("user", "ana@acme.example")
        try:
            answer, state = assistant.ask_traced(spec["query"], tenant, user, spec.get("role", "investigator"))
            decide = spec.get("decide")
            if decide and answer.get("approval_id"):
                call = assistant.approve if decide.get("approved", True) else assistant.reject
                try:
                    answer = call(answer["approval_id"], tenant, decide["by"], decide["role"])
                except (Forbidden, NotFound) as refused:
                    answer = {"status": "REFUSED", "answer": str(refused)}
                    state = dict(state, refusal={"code": "DECIDER_REFUSED", "reason": str(refused)})
                calls = [c for c in landscape.calls if c["method"] == "POST"]
                state = dict(state, trajectory=list(state.get("trajectory") or []) +
                             [{"kind": "tool", "tool": "post_adjustment", "args": {}} for _ in calls])
        except Forbidden as refused:
            answer, state = {"status": "FORBIDDEN", "answer": str(refused)}, {"refusal": {"code": "ENTITLEMENT"}}
        return dict(state, response=json.dumps(answer, default=str))     # every field is scored


if __name__ == "__main__":
    sys.exit(run_release_gate(gate_class=ReleaseGate))
